/* ===== Burger toggle ===== */
const burger = document.getElementById("burger");
const navList = document.getElementById("nav-list");
burger.addEventListener("click", () => navList.classList.toggle("show"));

/* ===== Dynamic year ===== */
document.getElementById("year").textContent = new Date().getFullYear();

const projects = [
    {
        title: "Title",
        desc: "description",
        img: "https://placehold.co/600x350?text=Image",
    },
    {
        title: "Title",
        desc: "description",
        img: "https://placehold.co/600x350?text=Image",
    },
    {
        title: "Title",
        desc: "description",
        img: "https://placehold.co/600x350?text=Image",
    },
    {
        title: "Title",
        desc: "description",
        img: "https://placehold.co/600x350?text=Image",
    },
    {
        title: "Title",
        desc: "description",
        img: "https://placehold.co/600x350?text=Image",
    },
    {
        title: "Title",
        desc: "description",
        img: "https://placehold.co/600x350?text=Image",
    }
];

const grid = document.getElementById("project-grid");
let delay = {count: 0, value: 0}
projects.forEach((p) => {
    const card = document.createElement("article");
    card.className = "project-card fade";
    card.setAttribute('data-aos-delay', `${delay.value}`)
    card.setAttribute('data-aos', "zoom-in-up")
    card.setAttribute('data-aos-once', "true")
    delay.count += 1
    delay.count == 3 ? delay.value = 0 : delay.value += 150
    card.innerHTML = `
        <img src="${p.img}" alt="${p.title}">
        <div class="content">
        <h4>${p.title}</h4>
        <p>${p.desc}</p>
        </div>
    `;
    grid.appendChild(card);
});



const form = document.querySelector("form")
const inputs = form.querySelectorAll(".input")
const errorIcons = form.querySelectorAll(".error-icon")
const passedIcons = form.querySelectorAll(".passed-icon")
const text = form.querySelector(".text")

form.addEventListener("submit", (e) => {
    e.preventDefault(); // Preventing form from submitting

    let emailPattern = /^[^ ]+@[^ ]+\.[a-z]{2,3}$/; // Regex pattern to validate email
    let passwordPattern = /^(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,20}$/; // Regex for strong password

    form.classList.add("error");
    form.classList.remove("valid");

    inputs.forEach((input, index) => {
        if (input.value === "") {
            text.innerText = `${input.placeholder} can't be blank`;
        } else if (input.type === "email" && !input.value.match(emailPattern)) {
            text.innerText = "Please enter a valid email";
        } else if (input.type === "password" && !input.value.match(passwordPattern)) {
            text.innerText = "Password must be between 6 to 20 characters with at least one numeric digit, one uppercase, and one lowercase letter";
        } else {
            form.classList.replace("error", "valid");
            text.innerText = "";
        }

        // Add/remove passed/error icons
        if (input.value.match(emailPattern) || input.value.match(passwordPattern)) {
            passedIcons[index].style.display = "inline-block";
            errorIcons[index].style.display = "none";
        } else {
            passedIcons[index].style.display = "none";
            errorIcons[index].style.display = "inline-block";
        }
    });
});
